async function DEQUEUE(rtn) {
  if (rtn = await QUEUED$(rtn)) {
    return put(rtn, C_RTN, 0);
  } else {
    return false;
  }
}

async function QUEUED$(rtn) {
  let c_ = 0, e = 0;
  e = g.C_TABLE + C_TABLELEN;
  c_ = g.C_TABLE + g.C_INTS;
  for (;;) {
    if (c_ == e) {
      return false;
    } else if (eq(get(c_, C_RTN), rtn)) {
      if (get(c_, C_TICK) == 0) {
        return false;
      } else {
        return c_;
      }
    }
    c_ = c_ + C_INTLEN;
  }
}

async function QUEUE(rtn, tick) {
  let c_ = 0, e = 0, int = false;
  e = g.C_TABLE + C_TABLELEN;
  c_ = g.C_TABLE + g.C_INTS;
  loop1: for (;;) {
    if (c_ == e) {
      if (int) {
        c_ = int;
      } else {
        g.C_INTS = g.C_INTS - C_INTLEN;
        int = g.C_TABLE + g.C_INTS;
      }
      put(int, C_RTN, rtn);
      break loop1;
    } else if (eq(get(c_, C_RTN), rtn)) {
      int = c_;
      break loop1;
    } else if (get(c_, C_RTN) == 0) {
      int = c_;
    }
    c_ = c_ + C_INTLEN;
  }
  if (int > g.CLOCK_HAND) {
    tick = -(tick + 3);
  }
  put(int, C_TICK, tick);
  return int;
}

async function CLOCKER() {
  let e = 0, tick = 0, rtn = 0, flg = false, q$ = false, owinner = 0;
  if (g.CLOCK_WAIT) {
    g.CLOCK_WAIT = false;
    return false;
  }
  g.CLOCK_HAND = g.C_TABLE + g.C_INTS;
  e = g.C_TABLE + C_TABLELEN;
  owinner = g.WINNER;
  g.WINNER = PLAYER;
  for (;;) {
    if (g.CLOCK_HAND == e) {
      g.CLOCK_HAND = e;
      g.MOVES = g.MOVES + 1;
      g.WINNER = owinner;
      return flg;
    } else if (!(get(g.CLOCK_HAND, C_RTN) == 0)) {
      tick = get(g.CLOCK_HAND, C_TICK);
      if (tick < (-1)) {
        put(g.CLOCK_HAND, C_TICK, (-tick) - 3);
        q$ = g.CLOCK_HAND;
      } else if (!(tick == 0)) {
        if (tick > 0) {
          tick = tick - 1;
          put(g.CLOCK_HAND, C_TICK, tick);
        }
        if (!(tick == 0)) {
          q$ = g.CLOCK_HAND;
        }
        if (!(tick > 0)) {
          rtn = get(g.CLOCK_HAND, C_RTN);
          if (tick == 0) {
            put(g.CLOCK_HAND, C_RTN, 0);
          }
          if (await apply(rtn)) {
            flg = true;
          }
          if (!q$ && !(get(g.CLOCK_HAND, C_RTN) == 0)) {
            q$ = true;
          }
        }
      }
    }
    g.CLOCK_HAND = g.CLOCK_HAND + C_INTLEN;
    if (!q$) {
      g.C_INTS = g.C_INTS + C_INTLEN;
    }
  }
}

