async function GENERIC_CUBE_F(tbl, len) {
  let f = 0, cnt = 1, cont = false, cube$ = 0;
  if (isVerb(V.ASK_ABOUT, V.TELL_ME_ABOUT, V.COUNT)) {
    return get(tbl, cnt);
  } else {
    if (isVerb(V.TAKE) && eq(get(g.P_ITBL, P_PREP2), PR.FROM) && eq(get(g.P_PRSI, g.P_MATCHLEN), 1)) {
      cont = get(g.P_PRSI, 1);
    }
    for (;;) {
      if (cnt > len) {
        return false;
      }
      f = get(tbl, cnt);
      cube$ = getPropAddr(f, P.NAME);
      if (cube$ && ((await VISIBLE$(f)) || isVerb(V.ASK_ABOUT, V.TELL_ABOUT))) {
        if (getProp(f, P.NAME) == 0) {
          if (!cont || (loc(f) == cont)) {
            return f;
          }
        }
      }
      cnt = cnt + 1;
    }
  }
}

