async function I_ORATION() {
  g.OCOUNT = g.OCOUNT + 1;
  crlf();
  if (g.OCOUNT == 1) {
    g.ORATOR = SNEFFLE;
    tell(D(SNEFFLE), " of the Guild of Bakers is addressing the gathering. \"Do you know what this is doing to our business? Do you know how difficult it is to make those yummy butter pastries by hand? When a simple 'gloth' spell would fold the dough 83 times it was possible to make a profit, but now 'gloth' hardly works, and when it does, it usually folds the dough too often and the butter melts, or it doesn't come out the right size, or...\" He stops, apparently overwhelmed by the prospect of a world where the pastries have to be hand-made. \"Can't you do anything about this? You're supposed to know all about magic!\"");
  } else if (g.OCOUNT == 2) {
    g.ORATOR = HOOBLY;
    tell(D(HOOBLY), " of the Guild of Brewers stands, gesturing at the floury baker. \"You don't know what trouble is! Lately, what comes out of the vats, like as not, is cherry flavored or worse. The last vat, I swear it, tasted as if grues had been bathing in it. It takes magic to turn weird vegetables and water into good Borphee beer. Well, without magic, there isn't going to be any beer!\" This statement has a profound effect on portions of the crowd. You can hear rumblings from the back concerning Enchanters. The word \"traitors\" rises out of nowhere. Your fellow Enchanters are looking at one another nervously.");
  } else if (g.OCOUNT == 3) {
    g.ORATOR = GZORNENPLATZ;
    tell("A tall, gruff fellow begins to speak. This is ", D(GZORNENPLATZ), " of the Guild of Huntsmen. \"I'm a simple man, and I don't know much about magic. But I do know that the wild beasts are kept out of the towns and villages not just by the huntsmen, but by spells as well. Just yesterday, one of my men was attacked and badly wounded by a troop of rat-ants. They'd slipped the bounds set down by a 'fripple' spell somehow. Are we going to let the sorcerers loose rat-ants on us, and worse?\" He sits, glaring significantly at the now-angry clump of mages around you.");
  } else if (g.OCOUNT == 4) {
    g.ORATOR = ARDIS;
    g.CLEESHED$ = true;
    move(BLORPLE_SPELL, SPELL_BOOK);
    tell("As the huntsman's accusations are being absorbed and discussed, ", D(ARDIS), " of the Guild of Poets takes the floor. He begins to talk about magic rhyming and spelling aids, and their lack.\n\nIn the midst of his splendid peroration, just as he was sketching out an insulting mythological allusion in iambic hexameter, the poet turns even greener than usual. His chin elongates and his skin begins to look sort of slimy. In the blink of an eye there stands at the podium, not the orator, but rather a large orange newt. \"Breek! Co-ax! Co-ax!\" it protests.\n\nAs you look around the room in shock, you discover that Ardis is not alone. Each and every guildmaster in the room has been turned into a frog, salamander, or other amphibian! All but one, that is: yourself!\n\nNo! There is one other survivor. At the rear of the room, a ", D(SHADOW), " in a dark cloak slips quietly out the door.");
    await THIS_IS_IT(SHADOW);
    clearFlag(SHADOW, NDESCBIT);
    move(SHADOW, GUILD_HALL);
    await QUEUE(I_SHADOW_GOES.id, 1);
    await DEQUEUE(I_ORATION.id);
  }
  return crlf();
}

async function I_SAMARRA() {
  if (g.HERE == BELWIT_SQUARE || g.HERE == GUILD_HALL) {
    tell("\nOut of the corner of your eye, you see the dark-cloaked figure. At first oblivious to you, it straightens up, startled and surprised, then vanishes.\n");
    return true;
  } else {
    return g.SAMARRA$ = false;
  }
}

async function I_SHADOW_GOES() {
  if (loc(SHADOW) == GUILD_HALL) {
    await QUEUE(I_SHADOW_GOES.id, 1);
    move(SHADOW, BELWIT_SQUARE);
    if (g.HERE == GUILD_HALL) {
      crlf();
      await CTHE_PRINT(SHADOW);
      tell(", its cloak billowing, charges south into Belwit Square.\n");
      return true;
    } else {
      return false;
    }
  } else {
    move(EARTH_CUBE, BELWIT_SQUARE);
    move(SHADOW, GLOBAL_OBJECTS);
    clearFlag(SHADOW, TAKEBIT);
    clearFlag(SHADOW, TRYTAKEBIT);
    clearFlag(CLOUD, INVISIBLE);
    await QUEUE(I_CLOUD_GONE.id, 20);
    if (g.HERE == GUILD_HALL) {
      crlf();
      tell("Out in the square, there is a crashing noise like an explosion, and then a wisp of orange smoke drifts in through the door.\n");
      return true;
    } else if (g.HERE == BELWIT_SQUARE) {
      crlf();
      tell("The sinister figure, its face hidden in the shadows of a dark cowl, turns to face you. It nonchalantly jumps into the air, where it is engulfed in a huge explosion. A thick and acrid cloud of orange smoke fills the square. There is no sign of the figure.\n");
      return true;
    } else {
      return false;
    }
  }
}

