async function I_LISKON(nocr$ = false) {
  let sf = 0;
  if (!g.SHRINK_FLAG) {
    return false;
  }
  sf = g.SHRINK_FLAG;
  g.SHRINK_FLAG = false;
  if (!(sf == PLAYER)) {
    if (hasFlag(WEED, RMUNGBIT) && (sf == WEED)) {
      putProp(WEED, P.SIZE, 200);
    }
    if (await VISIBLE$(sf)) {
      if (!nocr$) {
        crlf();
      }
      if (sf == SNAKE) {
        tell("The serpent slowly and jerkily returns to its former size, swallowing its tail again in the process.\n");
        return true;
      } else {
        tell("With a rather unsettling lack of uniformity, ");
        await THE_PRINT(sf);
        tell(" returns to its former size.");
        if ((sf == WEED) && hasFlag(WEED, RMUNGBIT)) {
          if (loc(sf) == g.WINNER) {
            move(sf, g.HERE);
            tell(" It's too heavy to carry.");
          } else if (eq(loc(sf), BOTTLE)) {
            move(sf, await META_LOC(BOTTLE));
            remove(BOTTLE);
            tell(" It bursts the bottle!");
          } else if (eq(loc(sf), MAGIC_CARPET, RANDOM_CARPET)) {
            move(sf, await META_LOC(sf));
          }
        }
        return crlf();
      }
    } else {
      return false;
    }
  } else {
    g.SMALL_FLAG = false;
    if (!nocr$) {
      crlf();
    }
    tell("You feel stretched, wrung out, and pulled in all directions. You are growing.\n");
    if (eq(loc(PLAYER), CABINET, PAST_CABINET)) {
      return await TOO_LARGE(CABINET);
    } else if (loc(PLAYER) == ZIPPER) {
      return false;
    } else if (g.HERE == IN_PIPE || g.HERE == IN_PIPE_2 || g.HERE == IN_SEWER) {
      await TOO_LARGE(WATER_PIPE);
      return M_FATAL;
    } else if (g.HERE == IN_CHANNEL) {
      crlf();
      return await GOTO(OUBLIETTE);
    } else if (g.HERE == RUINED_PIPE) {
      crlf();
      return await GOTO(RUINS_ROOM);
    } else {
      return false;
    }
  }
}

