async function I_OTHER_ROCK() {
  let dir = 0, rrow = 0, rcol = 0, orow = 0, ocol = 0, drow = 0, dcol = 0;
  if (g.ROCK_LOC == g.OTHER_ROCK_LOC) {
    g.ROCK_MOVED$ = false;
    await DEQUEUE(I_OTHER_ROCK.id);
    await CTHE_PRINT(OTHER_ROCK);
    tell(", mesmerized by the looming presence of ");
    await THE_PRINT(ROCK);
    tell(", does not move.\n");
    return true;
  } else if (g.ROCK_MOVED$) {
    g.ROCK_MOVED$ = false;
    rrow = div(g.ROCK_LOC, 4);
    rcol = g.ROCK_LOC & 3;
    orow = div(g.OTHER_ROCK_LOC, 4);
    ocol = g.OTHER_ROCK_LOC & 3;
    drow = rrow > orow ? (rrow - orow) : (orow - rrow);
    dcol = rcol > ocol ? (rcol - ocol) : (ocol - rcol);
    crlf();
    if (g.OTHER_ROCK_LOC == 1) {
      if (!(g.ROCK_LOC == 4 || g.ROCK_LOC == 5 || g.ROCK_LOC == 8) && (((drow + dcol) & 1) == 0)) {
        dir = P.SW;
      } else if (!(g.ROCK_LOC == 5)) {
        dir = P.SOUTH;
      } else if (!(g.ROCK_LOC == 2)) {
        dir = P.EAST;
      }
    } else if (g.OTHER_ROCK_LOC == 4) {
      if (!(g.ROCK_LOC == 1 || g.ROCK_LOC == 2 || g.ROCK_LOC == 5) && (((drow + dcol) & 1) == 0)) {
        dir = P.NE;
      } else if (!(g.ROCK_LOC == 5)) {
        dir = P.EAST;
      } else if (!(g.ROCK_LOC == 8)) {
        dir = P.SOUTH;
      }
    } else if ((g.OTHER_ROCK_LOC == 5) && (g.ROCK_LOC == 1 || g.ROCK_LOC == 4)) {
      dir = g.ROCK_LOC == 4 ? P.EAST : P.SOUTH;
    } else if (rrow == orow) {
      if ((orow == 0) || ((orow == 1) && (ocol == 0))) {
        dir = P.SOUTH;
      } else if ((orow == 3) || prob(50)) {
        dir = P.NORTH;
      } else {
        dir = P.SOUTH;
      }
    } else if (rcol == ocol) {
      if ((ocol == 0) || ((ocol == 1) && (orow == 0))) {
        dir = P.EAST;
      } else if ((ocol == 3) || prob(50)) {
        dir = P.WEST;
      } else {
        dir = P.EAST;
      }
    } else if ((ocol == 0) && (orow == 3)) {
      if (prob(50)) {
        dir = P.EAST;
      } else {
        dir = P.NORTH;
      }
    } else if ((ocol == 3) && (orow == 3)) {
      if (prob(50)) {
        dir = P.WEST;
      } else {
        dir = P.NORTH;
      }
    } else if ((ocol == 3) && (orow == 0)) {
      if (prob(50)) {
        dir = P.WEST;
      } else {
        dir = P.SOUTH;
      }
    } else if ((rrow > orow) && (orow > 0) && ((orow > 1) || (ocol > 0))) {
      dir = P.NORTH;
    } else if ((rcol > ocol) && (ocol > 0) && ((ocol > 1) || (orow > 0))) {
      dir = P.WEST;
    } else if ((rrow < orow) && (orow < 3)) {
      dir = P.SOUTH;
    } else if ((rcol < ocol) && (ocol < 3)) {
      dir = P.EAST;
    }
    if (dir == P.EAST) {
      ocol = ocol + 1;
    } else if (dir == P.WEST) {
      ocol = ocol - 1;
    } else if (dir == P.SOUTH) {
      orow = orow + 1;
    } else if (dir == P.NORTH) {
      orow = orow - 1;
    } else if (dir == P.NE) {
      orow = orow - 1;
      ocol = ocol + 1;
    } else {
      orow = orow + 1;
      ocol = ocol - 1;
    }
    g.OTHER_ROCK_LOC = (4 * orow) + ocol;
    if (loc(PLAYER) == OTHER_ROCK) {
      g.YOU_LOC = g.OTHER_ROCK_LOC;
    }
    await CTHE_PRINT(OTHER_ROCK);
    tell(" slides gracefully ");
    if (dir = await DIR_BASE(dir, DIR_DIR, DIR_NAME)) {
      tell(S(dir));
    }
    tell(S(g.PERIOD));
    return true;
  } else {
    return false;
  }
}

