async function FIND_IN(where, what) {
  let w_ = 0;
  w_ = 0;
  for (;;) {
    w_ = first(where);
    for (;;) {
      if (!w_) {
        return false;
        return true;
      }
      if (hasFlag(w_, what) && (await VISIBLE$(w_))) {
        return w_;
      }
      w_ = next(w_);
    }
  }
}

