async function IKILL(str) {
  if (!g.PRSO) {
    tell(S(g.THERES_NOTHING_TO), S(str), " here.\n");
  } else if (!g.PRSI && (loc(KNIFE) == g.WINNER)) {
    g.PRSI = KNIFE;
    tell("(with ");
    await THE_PRINT_PRSI();
    tell(")\n");
    await PERFORM(V.KILL, g.PRSO, g.PRSI);
    return true;
  }
  if (hasFlag(g.PRSO, DOORBIT)) {
    tell("Pounding on a door is of little use.\n");
    return true;
  } else if (!(hasFlag(g.PRSO, PERSON))) {
    tell("How strange. Fighting ");
    return await A_PRSO$();
  } else if ((g.PRSI == false || g.PRSI == HANDS) || !(hasFlag(g.PRSI, WEAPONBIT))) {
    tell("Trying to ", S(str), " ");
    await THE_PRINT_PRSO();
    tell(" with ");
    if (!(g.PRSI == false || g.PRSI == HANDS)) {
      await PRINTA_PRSI();
    } else {
      tell("your bare hands");
    }
    tell(" is suicidal.\n");
    return true;
  } else if (!(loc(g.PRSI) == g.WINNER)) {
    return await NOT_HOLDING(g.PRSI);
  } else {
    return await NOT_TRAINED();
  }
}

