async function V_SPELLS() {
  let s_ = 0, any = false, os = false, tmp = 0, cnt = 0;
  tell("The gnusto, rezrov, and frotz spells are yours forever. Other than that, you have ");
  cnt = 0;
  loop1: for (;;) {
    cnt = get(g.ALL_SPELLS, 0);
    loop2: for (;;) {
      if (cnt < 1) {
        break loop2;
      }
      if (tmp = await SPELL_TIMES(get(g.ALL_SPELLS, cnt))) {
        if (os) {
          await SPELL_PRINT(os, any);
          any = true;
        }
        os = tmp;
      }
      cnt = cnt + (-1);
    }
    break loop1;
  }
  if (os) {
    await SPELL_PRINT(os, any, true);
    any = true;
  }
  if (!any) {
    tell("no spells memorized.");
  } else {
    tell(" committed to memory.");
  }
  crlf();
  return true;
}

async function SPELL_PRINT(s_, any, pand$ = false) {
  let x = 0;
  if (any) {
    if (pand$) {
      tell(" and ");
    } else {
      tell(", ");
    }
  }
  await THE_PRINT(s_);
  tell(" ");
  x = getProp(s_, P.COUNT) - 1;
  if (x > 4) {
    x = 4;
  }
  tell(S(get(g.COUNTERS, x)));
  return s_;
}

async function SPELL_TIMES(s_) {
  if ((getProp(s_, P.COUNT) > 0) && (loc(s_) == SPELL_BOOK)) {
    return s_;
  } else {
    return false;
  }
}

