async function DETECT_MAGIC(obj, _1st$ = true) {
  let f = 0;
  f = 0;
  for (;;) {
    f = first(obj);
    for (;;) {
      if (!f) {
        return !_1st$;
        return true;
      }
      if (!(f == PLAYER || f == PILE_1 || f == PILE_2)) {
        if ((await VISIBLE$(f)) && (await MAGIC$(f))) {
          _1st$ = false;
          await CTHE_PRINT(f);
          tell(S(g.IS_GLOWING), "\n");
        } else if ((await SEE_INSIDE$(f)) && first(f)) {
          if (await DETECT_MAGIC(f, _1st$)) {
            _1st$ = false;
          }
        }
      }
      f = next(f);
    }
  }
}

