async function V_TINSOT() {
  g.ICED_OBJECT = g.PRSO;
  if ((g.HERE == OUBLIETTE) && ((g.PRSO == INFLOW || g.PRSO == OUTFLOW || g.PRSO == OUBLIETTE_CHANNEL) || (g.PRSO == WATER))) {
    if ((g.WATER_FLAG > 0) && !(g.PRSO == WATER)) {
      tell(S(g.YOU_CANT_SEE), "that anymore", S(g.PERIOD));
      return true;
    } else if (g.PRSO == INFLOW) {
      return await PARTIAL_BLOCKAGE(INFLOW);
    } else if (g.WATER_FLAG == 0) {
      await QUEUE(I_TINSOT.id, 30);
      g.ICED_OBJECT = OUTFLOW;
      g.FREEZE_FLAG = g.FREEZE_FLAG + 1;
      if (g.FREEZE_FLAG == 1) {
        return await PARTIAL_BLOCKAGE(OUTFLOW);
      } else if (g.FREEZE_FLAG == 2) {
        await QUEUE(I_OUBLIETTE_FILLS.id, -1);
        tell("In a dazzling purple flash, more water freezes, forming a large icy cap over the outflow pipe in the channel. Water continues to pour in the inflow, and it spills over the edge of the channel and begins to fill the room.\n");
        return true;
      } else {
        return false;
      }
    } else if (!(loc(ICEBERG) == g.HERE)) {
      move(ICEBERG, g.HERE);
      g.ICED_OBJECT = ICEBERG;
      tell("The purple flash freezes a small ice floe in the frigid water. It has a nice flat top.\n");
      return true;
    } else {
      tell(S(g.NOTHING_HAPPENS));
      return true;
    }
  } else if (g.PRSO == AIR) {
    return await V_SQUEEZE();
  } else if ((g.PRSO == BOTTLE || g.PRSO == WATER || g.PRSO == LOCAL_WATER) && (loc(LOCAL_WATER) == BOTTLE)) {
    remove(LOCAL_WATER);
    remove(BOTTLE);
    tell("The water and bottle freeze and shatter into a million pieces!\n");
    return true;
  } else {
    await CTHE_PRINT_PRSO();
    tell(" is covered with a thin film of ice.");
    if (hasFlag(g.PRSO, PERSON)) {
      tell(" ");
      await CTHE_PRINT_PRSO();
      tell(" shakes and shivers, and the ice cracks and peels away.");
    }
    return crlf();
  }
}

