async function BLANK_SCROLL_F() {
  let ot = 0, dt = 0;
  if (isVerb(V.COPY)) {
    if (!(loc(BURIN) == g.WINNER)) {
      return await NO_BURIN();
    } else if (!(g.PRSI == BLANK_SCROLL)) {
      return false;
    } else if (hasFlag(g.PRSI, RMUNGBIT)) {
      await CTHE_PRINT_PRSI();
      tell(" is too wet.\n");
      return true;
    } else if (first(g.PRSI)) {
      return await ALREADY_USED();
    } else if (!(hasFlag(g.PRSO, SPELLBIT))) {
      return false;
    } else if (eq(loc(g.PRSO), SPELL_BOOK, DEAD_BOOK)) {
      tell("Spell books are copy-protected to prevent spell thieves from making spell scrolls from another mage's spell book.\n");
      return true;
    } else if ((g.PRSO == GIRGOL_SPELL) && !(await HELD$(MAGIC_CUBE))) {
      tell("You try hard to copy the obscure runes and ideographs of the spell, but your mind just can't comprehend them, and your fingers just can't follow the curves and strokes.\n");
      return true;
    } else {
      dt = getPropAddr(g.PRSO, P.ADJECTIVE);
      ot = getPropAddr(SPELL_COPY, P.ADJECTIVE);
      putb(dt, 0, getb(ot, 0));
      putb(ot, 0, getb(dt, 1));
      putProp(SPELL_COPY, P.TEXT, getProp(g.PRSO, P.TEXT));
      move(SPELL_COPY, loc(g.PRSO));
      setFlag(g.PRSO, RWATERBIT);
      move(g.PRSO, g.PRSI);
      putProp(SPELL_COPY, P.WALLS, g.PRSO);
      putProp(SPELL_COPY, P.EXITS, await SPELL_TO_VERB());
      tell("Copied.\n");
      return true;
    }
  } else if (!(first(g.PRSO))) {
    if (isVerb(V.EXAMINE)) {
      tell(S(g.IT_LOOKS_LIKE), "a blank piece of vellum scroll paper.\n");
      return true;
    } else if (isVerb(V.READ)) {
      tell("This scroll is blank.\n");
      return true;
    } else if (isVerb(V.WRITE) && (g.PRSO == QWORD)) {
      tell("You should write spells, not random words, on spell paper.\n");
      return true;
    } else if (isVerb(V.WRITE) && !(hasFlag(g.PRSO, SPELLBIT))) {
      tell("That's not a spell! You'll waste good spell paper!\n");
      return true;
    } else {
      return false;
    }
  } else {
    return await SCROLL_F();
  }
}

async function DIR_BASE(dir, i, o) {
  let l = get(g.DIR_TABLE, 0), cnt = 0;
  cnt = 0;
  for (;;) {
    cnt = 0;
    for (;;) {
      if (cnt > l) {
        return true;
      }
      if (eq(get(g.DIR_TABLE, cnt + i), dir)) {
        return get(g.DIR_TABLE, cnt + o);
      }
      cnt = cnt + 3;
    }
  }
}

async function NOT_HERE_OBJECT_F() {
  let tbl = 0, prso$ = true, obj = 0, x = false;
  if ((g.PRSO == NOT_HERE_OBJECT) && (g.PRSI == NOT_HERE_OBJECT)) {
    tell("Those things aren't here!\n");
    return true;
  } else if (g.PRSO == NOT_HERE_OBJECT) {
    tbl = g.P_PRSO;
    if (isVerb(V.FOLLOW, V.LEARN, V.WHAT) || isVerb(V.WHERE, V.WHO, V.WAIT_FOR) || isVerb(V.CAST, V.WALK_TO, V.FIND)) {
      x = true;
    }
  } else {
    tbl = g.P_PRSI;
    if (isVerb(V.ASK_ABOUT, V.ASK_FOR, V.TELL_ABOUT)) {
      x = true;
    }
    prso$ = false;
  }
  if (x) {
    if (obj = await FIND_NOT_HERE(tbl, prso$)) {
      if (!(obj == NOT_HERE_OBJECT)) {
        return true;
      }
    } else {
      return false;
    }
    if (!(isVerb(V.FIND, V.FOLLOW, V.WHERE)) && !(isVerb(V.LEARN, V.CAST))) {
      tell(S(g.MORE_SPECIFIC), ", I'm afraid.\n");
      return true;
    }
  }
  if (g.WINNER == PLAYER) {
    tell("You");
  } else {
    await CTHE_PRINT(g.WINNER);
  }
  tell(" can't see");
  if (!(await NAME$(g.P_XNAM))) {
    tell(" any");
  }
  await NOT_HERE_PRINT(prso$);
  tell(" here.\n");
  return await END_QUOTE();
}

