async function RETREAT_F(rarg) {
  if (rarg == M_LOOK) {
    tell("The Enchanters' Retreat is an old stone structure perched high in the mountains. For generations, retired (or even burnt-out) enchanters have come here to breathe the clean mountain air, watch the stars, and rest from their exertions. The appointments are simple, the fare is unsophisticated, but those here have a look of quiet contentment that is easy for you to envy.\n");
    return true;
  } else if (rarg == M_BEG) {
    if (isVerb(V.WALK)) {
      tell("Belboz stops you. \"You should not even be here. You will disturb our rest.\"\n");
      return true;
    } else if (isVerb(V.ANSWER, V.YES, V.NO)) {
      await PERFORM(V.REPLY, BELBOZ);
      return true;
    } else if (isVerb(V.SAY) && g.BELBOZ_ASKS && !g.BELBOZ_CONVINCED$) {
      await QUOTED_PHRASE(g.P_CONT - P_LEXELEN, ACT.ANSWER);
      return await ORPHAN_VERB(W.ANSWER, ACT.ANSWER);
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function BELBOZ_F(rarg = false) {
  if (g.WINNER == BELBOZ) {
    if (isVerb(V.TELL_ABOUT) && (g.PRSO == ME)) {
      return false;
    } else if (isVerb(V.HELLO)) {
      tell("\"Hello.\" Belboz doesn't seem pleased to see you.\n");
      return true;
    } else if (!g.BELBOZ_CONVINCED$) {
      tell("Belboz looks at you suspiciously. ");
      if (g.BELBOZ_ASKS) {
        tell("\"Please answer my question, or I shall be forced to conclude you are an imposter.\"\n");
        return true;
      } else {
        tell("\"You were here a few days ago, or rather someone who resembled you strongly enough to be your twin was here. This being betrayed its true nature, however, as it did not know facts which would be trifles to even the rawest apprentice. It fled before I could capture it. Prove to me that you are truly yourself, and answer me a question. ");
        g.BELBOZ_ASKS = random(get(g.QUESTIONS, 0));
        await ORPHAN_VERB(W.ANSWER, ACT.ANSWER);
        tell(S(get(g.QUESTIONS, g.BELBOZ_ASKS)), "?\"\n");
        return true;
      }
    } else if (isVerb(V.GIVE)) {
      tell("\"All in good time.\"\n");
      return true;
    } else if (isVerb(V.HELP) && (g.PRSO == false || g.PRSO == ME)) {
      tell("The great mage looks tired. \"That is beyond my power,\" he says. \"I have given up worldly affairs. My time is past, I am old, and the world is now in the care of my successors. I am convinced you will not fail.\"\n");
      return true;
    } else if (isVerb(V.TELL_ME_ABOUT)) {
      if (g.PRSO == MAGIC) {
        tell("\"I can tell you nothing which you do not already know. We live in perilous times.\"\n");
        return true;
      } else if (g.PRSO == SHADOW) {
        tell("\"I have encountered such creatures, but this one is unfamiliar to me. They are sometimes spirits of the dead, or demons, or even illusory sendings.\"\n");
        return true;
      } else if (g.PRSO == SNAKE) {
        tell("\"This serpent brings to mind the great Ouroboros, said to encircle the world.\"\n");
        return true;
      } else if (g.PRSO == KEY) {
        tell("\"It was left nearby.\"\n");
        return true;
      } else if (getProp(g.PRSO, P.CUBE)) {
        if (await HELD$(g.PRSO)) {
          tell("Belboz looks at the cube for a while, turning it over and over in his hands.");
        } else {
          tell("Belboz thinks for a while.");
        }
        tell(" \"There is a legend about cubes. When the foundations of the world were laid down, it is said that the elemental powers and forces were symbolized during the making by small cubes. The cubes and the forces were merged in a way that our knowledge no longer comprehends. When the making was done, the cubes were hidden away where their powers could not be tampered with. If someone has gained access to them, or rediscovered the knowledge of their making, we are in terrible danger. One who had power over these cubes could change the very structure of our universe. Such a one would have powers I do not care to contemplate.\"");
        if (await HELD$(g.PRSO)) {
          tell(" Belboz gives back the cube.");
        }
        return crlf();
      } else if (g.PRSO == PSEUDO_OBJECT) {
        tell("\"I know little you do not know yourself.\"\n");
        return true;
      } else {
        tell("\"I know nothing of interest about that.\"\n");
        return true;
      }
    } else {
      tell("Belboz looks at you, but says nothing.\n");
      return true;
    }
  } else if (rarg == M_CONTAINER) {
    if (isVerb(V.TAKE)) {
      return await FORLORN_ENCYSTMENT();
    } else {
      return false;
    }
  } else if (!rarg) {
    if (isVerb(V.TELL) && g.BELBOZ_ASKS && !g.BELBOZ_CONVINCED$) {
      await ORPHAN_VERB(W.ANSWER, ACT.ANSWER);
      return false;
    } else if (isVerb(V.EXAMINE)) {
      tell("Belboz looks the same as always, ageless at an age when most have already departed the world. Outwardly, he seems relaxed and carefree.\n");
      return true;
    } else if (isVerb(V.SHOW)) {
      g.WINNER = BELBOZ;
      await PERFORM(V.TELL_ME_ABOUT, g.PRSO);
      g.WINNER = PLAYER;
      return true;
    } else if (isVerb(V.ASK_FOR)) {
      g.WINNER = BELBOZ;
      await PERFORM(V.GIVE, ME, g.PRSO);
      g.WINNER = PLAYER;
      return true;
    } else if (isVerb(V.WHO)) {
      tell("Belboz the Necromancer was head of the Accardi-by-the-sea chapter of the Guild of Enchanters until his recent retirement. You owe your position (and your life) to him, and it is partly because he was your mentor that you have achieved your present position. When he retired, he expressed an interest in rest, meditation and learning to arrange flowers.\n");
      return true;
    } else if (!g.BELBOZ_CONVINCED$ && (isVerb(V.REPLY) && (g.PRSO == BELBOZ) && !g.PRSI)) {
      await ORPHAN_VERB(W.ANSWER, ACT.ANSWER);
      tell("\"Yes? What is the answer?\"\n");
      return true;
    } else if (isVerb(V.REPLY)) {
      return await ANSWER_BELBOZ();
    } else if (isVerb(V.YOMIN)) {
      tell("You sense peacefulness");
      if (!g.BELBOZ_CONVINCED$) {
        tell(" overlaid upon a foundation of worry");
      }
      tell(S(g.PERIOD));
      return true;
    } else if ((await HOSTILE_VERB$()) || isVerb(V.ESPNIS, V.LISKON, V.SNAVIG) || isVerb(V.TINSOT)) {
      tell("Belboz stops you with a word of power.\n");
      return await FORLORN_ENCYSTMENT();
    } else if (isVerb(V.WHERE, V.FIND)) {
      if (!(loc(BELBOZ) == g.HERE) && !(hasFlag(RETREAT, TOUCHBIT))) {
        tell("You last saw Belboz months ago, when he left for the Enchanters' Retreat in the mountains.\n");
        return true;
      } else {
        tell("I would assume he is still at the Retreat.\n");
        return true;
      }
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function ANSWER_BELBOZ() {
  if (g.BELBOZ_ASKS && !g.BELBOZ_CONVINCED$) {
    if ((g.PRSO == PSEUDO_OBJECT || g.PRSO == BELBOZ) && (g.PRSI == false || g.PRSI == PSEUDO_OBJECT)) {
      if (!(await CORRECT$(get(g.ANSWERS, g.BELBOZ_ASKS)))) {
        g.FAKE_KEY = true;
      }
      g.SCORE = g.SCORE + 25;
      g.BELBOZ_CONVINCED$ = true;
      tell("\"Good! I knew it was you all along. What may I do for you?\"");
      if (loc(KEY) == BELBOZ) {
        clearFlag(KEY, NDESCBIT);
        move(KEY, g.WINNER);
        tell(" He fumbles in his pouch for a moment. \"First, let me give you this.\" He hands you a ", D(KEY), ". \"It may prove useful.\"");
      }
      return crlf();
    } else {
      return await FORLORN_ENCYSTMENT();
    }
  } else {
    tell("\"I asked no question,\" says Belboz.\n");
    return true;
  }
}

async function FORLORN_ENCYSTMENT() {
  g.DEATHS = 3;
  return (await JIGS_UP("\"Ah! Now I have you, charlatan! Fool me twice? Never!\" He rises to his feet, makes a threatening gesture, and you find yourself transported to a tiny cell deep beneath the earth, all belongings stripped from you. In time, though it takes years and you are mad long since, you starve."));
}

async function CORRECT$(wrd) {
  if (wrd == g.P_PNAM) {
    return true;
  } else if ((wrd == W.BARBEL) && (g.P_PADJN == W.BARBEL || g.P_PADJN == false) && (g.P_PNAM == W.GURTH)) {
    return true;
  } else if ((wrd == W.GUSTAR) && (g.P_PADJN == W.GUSTAR || g.P_PADJN == false) && (g.P_PNAM == W.WOOMAX)) {
    return true;
  } else if ((wrd == W.DIMITHIO) && (g.P_PADJN == W.DIMITHIO || g.P_PADJN == false) && (g.P_PNAM == W.BORPHEE)) {
    return true;
  } else if ((wrd == W.FORBURN) && (g.P_PADJN == W.FORBURN || g.P_PADJN == false) && (g.P_PNAM == W.WILY)) {
    return true;
  } else {
    return false;
  }
}

