async function COUNCIL_CHAMBER_F(rarg = false) {
  if (rarg == M_LOOK) {
    tell("You are in the Council Chamber of the ancient Guild Hall at Borphee. To the south is the entry of the Guild Hall. ");
    if (g.CLEESHED$) {
      tell("Scurrying wetly hither and yon around you are many brightly colored newts, efts, and salamanders. Toads and frogs hop excitedly about.");
    } else {
      tell("There is a meeting of the guildmasters going on. You are standing among a group of about ten sorcerers, each the master of an Enchanters Guild chapter somewhere in the land.");
      if (g.OCOUNT > 0) {
        tell(" ", D(g.ORATOR), " is addressing the meeting.");
      }
    }
    return crlf();
  } else if (rarg == M_BEG) {
    if (!g.CLEESHED$) {
      if (isVerb(V.WALK)) {
        tell("Annoyed guildmasters make way grudgingly. You hear muttering about \"arrogant enchanters\" as you try to leave the chamber. Finally, ", D(ORKAN), ", one of your colleagues, says, \"Stay. Be quiet. Don't embarrass us.\"\n");
        return true;
      } else if (isVerb(V.SAY) && !g.PRSO) {
        await END_QUOTE();
        tell(D(ORKAN), " quiets you. \"Interruptions will only annoy them.\"\n");
        return true;
      } else if (isVerb(V.LISTEN) && !g.PRSO) {
        tell(D(g.ORATOR), " is speaking.\n");
        return true;
      } else if (await SPELL_VERB$()) {
        tell(D(ORKAN), " stares at you in wonderment. \"Are you trying to get them even more mad at us?\" He makes a gesture of cancellation before you can finish the spell.\n");
        return true;
      } else if ((await HOSTILE_VERB$()) && hasFlag(g.PRSO, PERSON)) {
        if (g.PRSO == ORKAN) {
          tell(D(ORKAN), " easily subdues you without causing undue disruption.\n");
          return true;
        } else {
          tell(D(ORKAN), " grabs you and prevents your antisocial deed.\n");
          return true;
        }
      } else if (isVerb(V.YAWN, V.SLEEP)) {
        tell("Realizing how insulting you are being to the speaker, you try to stifle the yawn.\n");
        return true;
      } else {
        return false;
      }
    } else {
      return false;
    }
  } else {
    return false;
  }
}

