async function INITIALIZE_CUBES() {
  let cnt = 1, l = 0, buf = 0;
  l = g.FAKE_CUBE_LIST;
  buf = g.P_QBUF;
  loop1: for (;;) {
    if (++cnt > 13) {
      break loop1;
    }
    putProp(get(l, cnt), P.NAME, buf);
    buf = buf + 10;
  }
  put(buf, 0, 0);
  return g.P_QNEXT = buf;
}

async function CUBES_TO_PILES() {
  let l = 0, cnt = 0;
  l = g.FAKE_CUBE_LIST;
  cnt = 0;
  loop1: for (;;) {
    cnt = 2;
    loop2: for (;;) {
      if (cnt > 13) {
        break loop2;
      }
      move(get(l, cnt), PILE_1);
      cnt = cnt + 1;
    }
    break loop1;
  }
  if (TIME_CUBE == g.BLORPLE_OBJECT) {
    remove(TIME_CUBE);
    if (!g.TIME_CUBE_SCORE$) {
      g.TIME_CUBE_SCORE$ = true;
      clearFlag(TIME_CUBE, TOUCHBIT);
      await SCORE_OBJECT(TIME_CUBE);
    }
  }
  if (g.BLORPLE_OBJECT && loc(g.BLORPLE_OBJECT)) {
    return g.BLORPLE_OBJECT = false;
  } else {
    return false;
  }
}

async function JUGGLE_CUBES() {
  let buf = 0, p1 = 0, p2 = 0, q = 0, cnt = 0;
  await ROB(PILE_1, SCALES_ROOM);
  await ROB(PILE_2, SCALES_ROOM);
  cnt = 0;
  loop1: for (;;) {
    cnt = 2;
    loop2: for (;;) {
      if (cnt > 13) {
        break loop2;
      }
      q = await PICK_ONE(g.FAKE_CUBE_LIST);
      setFlag(q, NDESCBIT);
      if ((p2 == 6) || ((p1 < 6) && prob(50))) {
        p1 = p1 + 1;
        move(q, PILE_1);
      } else {
        move(q, PILE_2);
        p2 = p2 + 1;
      }
      cnt = cnt + 1;
    }
    break loop1;
  }
  buf = g.P_QBUF;
  q = 0;
  loop3: for (;;) {
    q = first(PILE_1);
    loop4: for (;;) {
      if (!q) {
        break loop4;
      }
      putProp(q, P.NAME, buf);
      put(buf, 0, await CUBE_ADJ(q));
      buf = buf + 10;
      q = next(q);
    }
    break loop3;
  }
  q = 0;
  loop5: for (;;) {
    q = first(PILE_2);
    loop6: for (;;) {
      if (!q) {
        break loop6;
      }
      putProp(q, P.NAME, buf);
      put(buf, 0, await CUBE_ADJ(q));
      buf = buf + 10;
      q = next(q);
    }
    break loop5;
  }
  return true;
}

