async function PILE_LOOP(obj) {
  let f = 0, n_ = 0, _1st$ = true, cnt = 0, cube$ = 0;
  f = 0;
  n_ = 0;
  for (;;) {
    f = first(obj);
    for (;;) {
      if (!f) {
        if (cnt > 0) {
          if (!_1st$) {
            tell(" and ");
          }
          tell(N(cnt), " ", S(g.WHITE_CUBE));
          if (cnt > 1) {
            tell("s");
          }
        }
        return true;
      }
      n_ = next(f);
      cube$ = getPropAddr(f, P.NAME);
      if (!cube$ || !(getProp(f, P.NAME) == 0)) {
        if (!_1st$) {
          if (!n_ && (cnt == 0)) {
            tell(" and ");
          } else {
            tell(", ");
          }
        } else {
          _1st$ = false;
        }
        if (!(getPropAddr(f, P.NAME))) {
          await PRINTA(f);
        } else {
          await THE_PRINT(f);
        }
      } else {
        cnt = cnt + 1;
      }
      f = n_;
    }
  }
}

