async function PLAIN_ROOM_F(rarg) {
  if (rarg == M_LOOK) {
    tell("This is a flat plain punctuated by boulders. The boulders are all identical and slide to and fro on the eerie surface, propelled by an unknown mechanism. The ground is scratched by many intersecting lines which seem to have a regular pattern. ");
    await DESCRIBE_PLAIN();
    tell(" Far in the distance are mountains which quiver itchily as they belch forth purple fire.\n");
    return true;
  } else if (rarg == M_BEG) {
    g.ROCK_MOVED$ = false;
    if ((g.WINNER == PLAYER) && isVerb(V.WALK)) {
      if (loc(PLAYER) == g.HERE) {
        tell("You find that the surface is too smooth. Your feet slip out from under you, and you crash to the ground.\n");
        return true;
      } else if (g.P_WALK_DIR == P.DOWN) {
        await PERFORM(V.DISEMBARK);
        return true;
      } else {
        tell(S(g.YOU_HAVE_TO), " get down off the rock if you want to walk.\n");
        return true;
      }
    } else {
      return false;
    }
  } else if (rarg == M_ENTER) {
    g.ROCK_LOC = 5;
    return g.YOU_LOC = 5;
  } else if (rarg == M_LEAVE) {
    g.ROCK_BRIBED$ = false;
    return await DEQUEUE(I_OTHER_ROCK.id);
  } else {
    return false;
  }
}

