async function DESCRIBE_PLAIN(rocks$ = true) {
  let $1;
  if (await HELD$(PLAYER, ROCK)) {
    tell("You are on a large, green eyed rock. ");
  }
  tell("From where you are ");
  if ((await HELD$(PLAYER, ROCK)) || (await HELD$(PLAYER, OTHER_ROCK))) {
    $1 = "perched";
  } else {
    $1 = "standing";
  }
  tell(S($1));
  tell(" you can see lines radiating ");
  await TELL_WALLS(getb(g.PLAIN_WALLS, g.YOU_LOC));
  tell(".");
  if (!rocks$) {
    return true;
  }
  if (!(g.YOU_LOC == g.ROCK_LOC) || !(loc(PLAYER) == ROCK)) {
    tell(" There is a large green eyed rock");
    if (!(loc(PLAYER) == ROCK)) {
      tell(" here");
    } else {
      await ROCK_DIRECTION(g.ROCK_LOC);
    }
    tell(".");
  }
  if (!(loc(PLAYER) == OTHER_ROCK)) {
    tell(" Also, there is a large brown eyed rock ");
    if (loc(DARK_CUBE) == OTHER_ROCK) {
      tell("with a ", S(g.WHITE_CUBE), " on its back ");
    }
    if (g.YOU_LOC == g.OTHER_ROCK_LOC) {
      tell("here");
    } else {
      await ROCK_DIRECTION(g.OTHER_ROCK_LOC);
    }
    tell(".");
    return true;
  } else {
    return false;
  }
}

async function ROCK_DIRECTION(r) {
  let row = 0, col = 0, rrow = 0, rcol = 0, drow = 0, dcol = 0;
  row = div(g.YOU_LOC, 4);
  col = g.YOU_LOC & 3;
  rrow = div(r, 4);
  rcol = r & 3;
  drow = rrow > row ? (rrow - row) : (row - rrow);
  dcol = rcol > col ? (rcol - col) : (col - rcol);
  if ((drow < 2) && (dcol < 2)) {
    tell("nearby and off");
  } else if ((drow < 3) && (dcol < 3)) {
    tell("some distance");
  } else {
    tell("quite a ways off");
  }
  tell(" to the ");
  if (rrow > row) {
    if (rcol > col) {
      tell("southeast");
      return true;
    } else if (rcol < col) {
      tell("southwest");
      return true;
    } else if (rcol == col) {
      tell("south");
      return true;
    } else {
      return false;
    }
  } else if (rrow < row) {
    if (rcol > col) {
      tell("northeast");
      return true;
    } else if (rcol < col) {
      tell("northwest");
      return true;
    } else if (rcol == col) {
      tell("north");
      return true;
    } else {
      return false;
    }
  } else {
    if (rcol > col) {
      tell("east");
      return true;
    } else {
      tell("west");
      return true;
    }
  }
}

