async function ROCK_F(rarg = false) {
  if (g.WINNER == ROCK) {
    if (isVerb(V.TELL_ABOUT) && (g.PRSO == ME)) {
      return false;
    } else if (isVerb(V.WALK, V.WALK_TO)) {
      if (isVerb(V.WALK) && (await HELD$(PLAYER, ROCK))) {
        await ROCK_WALK(g.P_WALK_DIR);
      } else if (g.ROCK_BRIBED$) {
        tell("\"Do you want to ride along? ");
        if (g.TRIED_BOARDING$) {
          tell("That's what you seemed to want. ");
        }
        tell("Do you have any more food?\"\n");
      } else {
        await WHATS_IN_IT_FOR_ME$();
      }
    } else if (isVerb(V.TELL_ME_ABOUT)) {
      if (g.PRSO == BREAD || g.PRSO == FISH) {
        tell("\"Yummy food? Food is crunchy and nice. I like it with lots of phosphorus!\"\n");
      } else if (g.PRSO == OTHER_ROCK) {
        tell("\"It's not as pretty as me.\"\n");
      } else {
        tell("\"I don't know much about that.\"\n");
      }
    } else if (isVerb(V.EAT)) {
      tell("\"You have food?\"\n");
    } else {
      await ROCK_SPEECHES();
    }
    return g.ROCK_TALKED$ = true;
  } else if (rarg == M_CONTAINER) {
    if (!(await HELD$(PLAYER, ROCK))) {
      return await CANT_REACH_THAT();
    } else {
      return false;
    }
  } else if (rarg == M_BEG) {
    if (isVerb(V.DISEMBARK, V.CLIMB_DOWN, V.LEAP) && (g.PRSO == false || g.PRSO == ROOMS || g.PRSO == ROCK)) {
      move(PLAYER, g.HERE);
      g.ROCK_BRIBED$ = false;
      tell("\"That was fun! I'm kind of tired from carrying you, though. Do you have any more food?\"\n");
      return true;
    } else {
      return false;
    }
  } else if (!rarg) {
    if (isVerb(V.EXAMINE)) {
      tell("This is a rather large boulder with a flat bottom. Something prevents it from touching the ground, as it moves about quite nimbly, watching you with lovely green eyes.");
      (await CLEVER_CONTENTS(ROCK, " On the rock"));
      return crlf();
    } else if (isVerb(V.ADMIRE)) {
      g.ROCK_TALKED$ = true;
      tell("\"You're very perceptive.\" The rock has no false modesty.\n");
      return true;
    } else if (isVerb(V.MOVE, V.PUSH)) {
      g.ROCK_TALKED$ = true;
      tell(S(g.IT_TICKLES));
      return true;
    } else if (isVerb(V.RUB)) {
      g.ROCK_TALKED$ = true;
      tell("\"Aren't I smooth?\" says the rock.\n");
      return true;
    } else if (isVerb(V.GIVE, V.SHOW) && (g.PRSI == ROCK)) {
      g.ROCK_TALKED$ = true;
      if (g.PRSO == BREAD || g.PRSO == FISH) {
        tell("\"What's that? Dead animal or vegetable matter! You won't fool me! Horrible! It would ruin my complexion!\"\n");
        return true;
      } else if (g.PRSO == LAVA_ROCK) {
        if (isVerb(V.GIVE)) {
          remove(LAVA_ROCK);
          g.ROCK_BRIBED$ = true;
          tell("\"Mmm. That looks good. Just the right size, too.\" It slides happily over the piece of lava and settles comfortably to the ground. You hear a sound like a rasp for a while. The rock blinks contentedly and rises into the air again.\n");
          return true;
        } else {
          tell("\"Oh, yum! Give it to me, please!\"\n");
          return true;
        }
      } else {
        tell("\"That doesn't look very appetizing.\"\n");
        return true;
      }
    } else if (isVerb(V.BOARD, V.SIT, V.CLIMB_ON, V.CLIMB_FOO, V.CLIMB_UP)) {
      g.ROCK_TALKED$ = true;
      g.TRIED_BOARDING$ = true;
      if (loc(PLAYER) == ROCK) {
        tell(S(g.IT_TICKLES));
        return true;
      } else if (g.ROCK_BRIBED$) {
        move(PLAYER, ROCK);
        tell("You climb the rock and perch precariously on top. From here you can see that the long scratches in the ground form a rectangular grid that fills a rather small valley. \"My back is the most hemispheric of all my friends',\" remarks the rock.\n");
        return true;
      } else {
        tell("The rock spins in place, preventing you from getting on. ");
        return await WHATS_IN_IT_FOR_ME$();
      }
    } else if (isVerb(V.LOOK_UNDER)) {
      g.ROCK_TALKED$ = true;
      tell("The rock's underside is perfectly smooth. When you look under it, the rock says, \"Hey! What is this? What about my privacy?\"");
      if (g.ROCK_BRIBED$) {
        tell(" There is no sign of the lava.");
      }
      return crlf();
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function WHATS_IN_IT_FOR_ME$() {
  tell("\"What's in it for me? For example, if you had some food, that might be nice. Then you could ride on top and admire me from that angle. It's a rare privilege.\"\n");
  return true;
}

async function ROCK_WALK(dir) {
  let row = 0, col = 0;
  await QUEUE(I_OTHER_ROCK.id, -1);
  if ((g.ROCK_LOC == 4) && (dir == P.NE)) {
    g.ROCK_LOC = 1;
  } else if ((g.ROCK_LOC == 1) && (dir == P.SW)) {
    g.ROCK_LOC = 4;
  } else {
    row = div(g.ROCK_LOC, 4);
    col = g.ROCK_LOC & 3;
    if ((dir == P.NORTH) && ((row > 1) || ((row > 0) && (col > 0)))) {
      row = row - 1;
    } else if ((dir == P.SOUTH) && (row < 3)) {
      row = row + 1;
    } else if ((dir == P.EAST) && (col < 3)) {
      col = col + 1;
    } else if ((dir == P.WEST) && ((col > 1) || ((col > 0) && (row > 0)))) {
      col = col - 1;
    } else {
      tell("The rock says, \"There isn't a line there. Do you want me to starve to death? Besides, what would my friends think if I was out of line?\"\n");
      return true;
    }
    g.ROCK_LOC = (row * 4) + col;
  }
  if (await HELD$(PLAYER, ROCK)) {
    g.YOU_LOC = g.ROCK_LOC;
  }
  g.ROCK_MOVED$ = true;
  tell("The rock glides smoothly, carefully following the line on the plain. \"Yum!\" it remarks, parenthetically. ");
  await DESCRIBE_PLAIN();
  remove(OTHER_ROCK);
  if (await ROB(g.HERE, false, ROCK)) {
    tell(" Something you left behind on the ground has been crushed by the rock.");
  }
  move(OTHER_ROCK, g.HERE);
  crlf();
  return true;
}

