async function WEED_F() {
  if (isVerb(V.EXAMINE)) {
    return await WEED_DETAILS(false);
  } else if (isVerb(V.TAKE, V.PICK, V.MOVE)) {
    if (hasFlag(WEED, RMUNGBIT) && !(g.SHRINK_FLAG == WEED)) {
      tell("I suppose you have the logging equipment to do this? If so, I don't see it anywhere.\n");
      return true;
    } else if (!(await HELD$(g.PRSO))) {
      if (g.WEED_PLANTED$ == 2) {
        if (eq(await ITAKE(), true)) {
          move(WEED, g.HERE);
          g.WEED_PLANTED$ = 1;
          tell("The weed pulls partly out of the ground.\n");
        }
        return true;
      } else if (g.WEED_PLANTED$ == 1) {
        if (eq(await ITAKE(), true)) {
          g.WEED_PLANTED$ = false;
          tell("The weed pulls out of the ground, taking a good-sized ball of earth with it.\n");
        }
        return true;
      } else {
        return false;
      }
    } else {
      return false;
    }
  } else if (isVerb(V.CUT) && (g.PRSI == KNIFE || g.PRSI == SHEARS)) {
    if (hasFlag(WEED, RMUNGBIT) && !(g.SHRINK_FLAG == WEED)) {
      tell("You would need an axe.\n");
      return true;
    } else {
      move(WEED, g.WINNER);
      setFlag(WEED, RWATERBIT);
      tell("You now have a weed cutting.\n");
      return true;
    }
  } else if (isVerb(V.PLANT) && ((g.PRSI == GROUND || g.PRSI == GLOBAL_CAVE) || ((g.PRSI == PSEUDO_OBJECT) && (g.P_PNAM == W.DIRT)) || (!g.PRSI && (hasFlag(g.HERE, OUTSIDE) || (g.HERE == OGRE_CAVE || g.HERE == OGRE_BEDROOM))))) {
    if (hasFlag(g.HERE, RLANDBIT) && !(getProp(g.HERE, P.CUBE)) && (loc(g.WINNER) == g.HERE)) {
      if (hasFlag(WEED, RWATERBIT)) {
        tell(S(g.YOU_CANT), "expect it to grow from such a cutting.\n");
        return true;
      } else {
        g.WEED_PLANTED$ = 2;
        move(WEED, g.HERE);
        tell("You plant the weed. ", S(g.IT_LOOKS_LIKE), "it might even thrive if it gets some attention.\n");
        return true;
      }
    } else {
      tell(S(g.I_DONT_THINK_THAT), "even a weed can grow here.\n");
      return true;
    }
  } else if (isVerb(V.THROCK)) {
    if (hasFlag(WEED, RWATERBIT)) {
      tell("The weed shivers, tries very hard to grow in its mutilated state and then gives up.\n");
      return true;
    } else if (!g.WEED_PLANTED$) {
      tell("The spell envelops the weed, quests around its roots looking for something, fails to find it and fades.\n");
      return true;
    } else if (hasFlag(WEED, RMUNGBIT)) {
      tell("The weed grows a few more inches and then stops.\n");
      return true;
    } else {
      putProp(WEED, P.SIZE, 200);
      setFlag(WEED, RMUNGBIT);
      tell("With a spurt of explosive growth, the weed expands to spectacular size. It is now as large as a small tree!");
      if (g.HERE == CAVE_ENTRANCE) {
        await OGRE_SNEEZING();
        tell(" After a few seconds, you hear a muffled exclamation from within the cave, and then a volley of sneezes.");
      } else if (g.HERE == OGRE_CAVE) {
        await OGRE_SNEEZING();
        tell(" As the weed grows, the ogre watches in horror. \"Ragweed!\" he screams, and then his further comments are cut off by a volley of sneezes like the reports of a small cannon. The ogre begins to rub his eyes, which are watering horrifically, and his sneezes are monumental. He is totally oblivious to your presence.");
      }
      return crlf();
    }
  } else if (isVerb(V.CASKLY)) {
    tell(S(g.NOTHING_HAPPENS));
    return true;
  } else if (isVerb(V.LISKON)) {
    if (await PRE_LISKON()) {
      return true;
    } else if (hasFlag(WEED, RMUNGBIT)) {
      g.SHRINK_FLAG = WEED;
      putProp(WEED, P.SIZE, 3);
      await QUEUE(I_LISKON.id, 15);
      tell("The weed shrinks back to almost exactly its former size.\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.SHAKE) && (g.HERE == OGRE_CAVE)) {
    await PERFORM(V.WAVE_AT, g.PRSO, OGRE);
    return true;
  } else {
    return false;
  }
}

