async function ARM_DIRECTION(n_) {
  let l = get(g.DIR_TABLE, 0), cnt = 0;
  cnt = 0;
  for (;;) {
    cnt = 1;
    for (;;) {
      if (cnt > l) {
        return true;
      }
      if (eq(get(g.DIR_TABLE, cnt), n_)) {
        return get(g.DIR_TABLE, cnt + 2);
      }
      cnt = cnt + 3;
    }
  }
}

