async function OCTAGONAL_HOLE_F() {
  let e = 0, pt = 0, pts = 0;
  if ((g.HERE == MAZE_2) && (loc(MAZE_2_DOOR) == g.HERE)) {
    return await MAZE_2_DOOR_F();
  } else if (isVerb(V.REZROV)) {
    tell(S(g.IT_IS_ALREADY), "open.\n");
    return true;
  } else if (isVerb(V.LOOK_INSIDE)) {
    tell(S(g.NOW_BLACK), "\n");
    return true;
  } else if (isVerb(V.EXAMINE)) {
    tell("It looks like an ", S(g.OCT_HOLE), S(g.PERIOD));
    return true;
  } else if (isVerb(V.PUT, V.THROW, V.DROP) && (await HELD$(g.PRSO)) && (g.PRSI == OCTAGONAL_HOLE)) {
    e = getProp(g.HERE, P.EXITS);
    e = await DIR_BASE(e, DIR_BIT, DIR_DIR);
    pt = getPropAddr(g.HERE, e);
    pts = propSize(pt);
    if ((pts == UEXIT) || ((pts == CEXIT) && globalValue(getb(pt, CEXITFLAG)))) {
      move(g.PRSO, getb(pt, REXIT));
      await CTHE_PRINT_PRSO();
      tell(" disappears into the hole.\n");
      return true;
    } else {
      tell("It won't go.\n");
      return true;
    }
  } else if (isVerb(V.THROUGH, V.BOARD)) {
    e = getProp(g.HERE, P.EXITS);
    if (e < 256) {
      return await DO_WALK(await DIR_BASE(e, DIR_BIT, DIR_DIR));
    } else {
      return false;
    }
  } else {
    return false;
  }
}

