async function MAZE_2_DOOR_F() {
  let open$ = !(loc(MAZE_2_DOOR) == g.HERE);
  if (isVerb(V.EXAMINE)) {
    await DESCRIBE_PLUG();
    return crlf();
  } else if (isVerb(V.TAKE, V.MOVE)) {
    if (!(hasFlag(g.PRSO, OPENBIT))) {
      tell("You can't budge it.\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.PUSH)) {
    if (open$) {
      tell(S(g.THERE_IS_NOTHING), "there to push on anymore.\n");
      return true;
    } else {
      tell(S(g.NOTHING_HAPPENS));
      return true;
    }
  } else if (isVerb(V.OPEN)) {
    tell("There is no apparent lock or handle.\n");
    return true;
  } else if (isVerb(V.CLOSE)) {
    if (open$) {
      return await NO_DOOR();
    } else {
      tell(S(g.IT_IS_ALREADY), "closed", S(g.PERIOD));
      return true;
    }
  } else if (isVerb(V.THROUGH)) {
    if (open$) {
      return await DO_WALK(P.WEST);
    } else {
      return await NO_DOOR();
    }
  } else if (isVerb(V.REZROV)) {
    putProp(g.HERE, P.EXITS, 4);
    setFlag(OCTAGONAL_HOLE, OPENBIT);
    remove(MAZE_2_DOOR);
    tell("The alabaster melts away, leaving an ", S(g.OCT_HOLE), " leading west.\n");
    return true;
  } else {
    return false;
  }
}

