async function MAZE_F(rarg) {
  let dir = 0, oexits = 0;
  let $1;
  if (rarg == M_LOOK) {
    tell("This room is in the shape of an octagonal solid carved from marble. The floor and ceiling are the octagons and each wall is a rectangle. On each wall is inlaid a rune indicating a direction: the north wall has \"north\" carved on it, and so on. The ");
    if (g.HERE == MAZE_1) {
      tell("runes are all of lead.");
    } else {
      if (g.HERE == MAZE_2) {
        tell("west rune is gold, the ");
      }
      await TELL_WALLS();
      tell(" runes are lead, the rest are of silver.");
    }
    if (!(getProp(g.HERE, P.EXITS) == 0)) {
      await DESCRIBE_MAZE_WALLS();
    }
    if ((g.HERE == MAZE_2) && (loc(MAZE_2_DOOR) == g.HERE)) {
      tell(" ");
      await DESCRIBE_PLUG();
    }
    return crlf();
  } else if (rarg == M_ENTER) {
    if (g.HERE == MAZE_2) {
      move(OCTAGONAL_HOLE, g.HERE);
      clearFlag(OCTAGONAL_HOLE, OPENBIT);
    }
    return clearFlag(g.HERE, TOUCHBIT);
  } else if (rarg == M_LEAVE) {
    if (g.HERE == MAZE_2) {
      move(MAZE_2_DOOR, MAZE_2);
      clearFlag(OCTAGONAL_HOLE, OPENBIT);
    }
    return putProp(g.HERE, P.EXITS, 0);
  } else if (rarg == M_BEG) {
    if (isVerb(V.WALK)) {
      dir = await DIR_BASE(g.P_WALK_DIR, DIR_DIR, DIR_BIT);
      if (!(eq(getProp(g.HERE, P.EXITS) & dir, 0))) {
        await OCT_HOLE_DISAPPEARS();
        return await V_WALK();
      } else {
        tell("There is no exit ");
        if (g.P_WALK_DIR == P.UP || g.P_WALK_DIR == P.DOWN) {
          tell("there");
        } else {
          tell("on that wall");
        }
        tell(S(g.PERIOD));
        return true;
      }
    } else if (isVerb(V.PUT, V.PUT_ON) && (g.PRSO == COMPASS_ROSE)) {
      if (await GLOBAL_IN$(g.PRSI, g.HERE)) {
        await PERFORM(V.RUB, g.PRSI, g.PRSO);
        return true;
      } else if ((loc(g.PRSI) == GLOBAL_OBJECTS) && getProp(g.PRSI, P.EXITS)) {
        tell(S(g.THERE_IS_NOTHING), "to hang it on.\n");
        return true;
      } else {
        return false;
      }
    } else if (isVerb(V.RUB) && (g.PRSI == COMPASS_ROSE)) {
      dir = getProp(g.PRSO, P.EXITS);
      if ((g.HERE == MAZE_2) && (dir == 4)) {
        tell(S(g.NOTHING_HAPPENS));
        return true;
      } else if (dir && eq(getProp(g.HERE, P.WALLS) & dir, 0) && eq(getProp(g.HERE, P.EXITS) & dir, 0) && eq(g.COMPASS_ROSE_STATE & dir, 0)) {
        g.COMPASS_ROSE_ARMS = g.COMPASS_ROSE_ARMS + 1;
        g.COMPASS_ROSE_STATE = g.COMPASS_ROSE_STATE | dir;
        oexits = getProp(g.HERE, P.EXITS);
        putProp(g.HERE, P.EXITS, dir);
        move(OCTAGONAL_HOLE, g.HERE);
        tell("As the compass rose touches the ", D(g.PRSO), ", the arm of the rose labelled \"");
        $1 = await ARM_DIRECTION(dir);
        tell(S($1));
        tell("\" turns dull and leaden, and an ", S(g.OCT_HOLE), " large enough for you to squeeze through appears in the wall below the rune.");
        if (!(oexits == 0)) {
          tell(" The other hole disappears.");
        }
        return crlf();
      } else {
        tell(S(g.NOTHING_HAPPENS));
        return true;
      }
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function TELL_WALLS(n_ = false) {
  let l = get(g.DIR_TABLE, 0), _1st$ = true, old = false, cnt = 0;
  if (!n_) {
    n_ = getProp(g.HERE, P.WALLS);
  }
  cnt = 0;
  for (;;) {
    cnt = 1;
    for (;;) {
      if (cnt > l) {
        tell(" and ", S(old));
        return true;
      }
      if (!((get(g.DIR_TABLE, cnt) & n_) == 0)) {
        if (old) {
          if (_1st$) {
            _1st$ = false;
          } else {
            tell(", ");
          }
          tell(S(old));
        }
        old = get(g.DIR_TABLE, cnt + 2);
      }
      cnt = cnt + 3;
    }
  }
}

