async function PAST_RUINS_ROOM_F(rarg) {
  if (rarg == M_LOOK) {
    tell("This is the south end of a vast chamber filled with partially ruined structures. Here the portico of a building is collapsing. The pillars holding it up are starting to crumble. One has recently fallen and smashed the pavement. The fall exposed and the rubble blocked a small channel filled with swiftly rushing water which is rapidly inundating the area. ", S(get(g.WATER_TABLE, g.PAST_WATER_FLAG)), "\n");
    return true;
  } else if (rarg == M_BEG) {
    if (isVerb(V.PUT) && (g.PRSI == WATER)) {
      remove(g.PRSO);
      await CTHE_PRINT_PRSO();
      tell(" is borne away by the flood.\n");
      return true;
    } else if (isVerb(V.THROUGH) && ((g.PRSO == WATER) || (g.P_PNAM == W.CHANNEL))) {
      if (g.PAST_WATER_FLAG > 2) {
        tell(S(g.YOU_ARE), S(g.PERIOD));
        return true;
      } else {
        tell("It's cold and icy.\n");
        return true;
      }
    } else {
      return false;
    }
  } else if (rarg == M_ENTER) {
    if (g.PAST_WATER_FLAG > 0) {
      g.DEATHS = 3;
      return (await JIGS_UP("You emerge underwater, amidst a dim and blurry vision of drowned columns. You drown as well."));
    } else {
      move(GIRGOL_SCROLL, SACK);
      setFlag(GIRGOL_SCROLL, TOUCHBIT);
      return await QUEUE(I_WATER_RISING.id, 3);
    }
  } else if (rarg == M_LEAVE) {
    remove(PLAYER);
    await DEQUEUE(I_WATER_RISING.id);
    if (!g.DEAD$ && (await ONLY$(ZIPPER, g.HERE)) && (await ONLY$(GIRGOL_SCROLL, ZIPPER)) && !(hasFlag(ZIPPER, OPENBIT))) {
      move(PLAYER, g.HERE);
      g.SCORE = g.SCORE + g.RUINS_SCORE;
      return g.RUINS_SCORE = 0;
    } else {
      move(PLAYER, g.HERE);
      move(GIRGOL_SCROLL, SACK);
      move(SACK, g.HERE);
      tell(S(g.TIME_SICK), "You feel that you are being pummelled by huge rocks and boulders");
      g.DEATHS = 3;
      return (await JIGS_UP(", again and again. Finally, you succumb."));
    }
  } else {
    return false;
  }
}

async function ONLY$(obj, con) {
  if (!(loc(obj) == con)) {
    return false;
  } else if (!(con = first(con))) {
    return false;
  } else if (!(obj == con)) {
    return false;
  } else if (next(con)) {
    return false;
  } else {
    return true;
  }
}

